def maxArea_tp(height):
    l, r = 0, len(height) - 1   # 从最宽的状态开始
    ans = 0
    while l < r:
        # 当前容量：宽度 × 两侧较矮者（木桶效应）
        ans = max(ans, min(height[l], height[r]) * (r - l))
        if height[l] < height[r]:
            l += 1              # 矮的一侧是瓶颈，向内换人可能更高
        else:
            r -= 1              # 右侧不高于左侧，同理收缩右侧
    return ans

