func maxArea(height []int) int {
	l, r := 0, len(height)-1 // 从最宽的状态开始
	ans := 0
	for l < r {
		// 当前容量：宽度 × 两侧较矮者（木桶效应）
		area := height[l]
		if height[r] < area {
			area = height[r] // 取两侧较矮者
		}
		if w := area * (r - l); w > ans {
			ans = w // 更新全局最大容量
		}
		if height[l] < height[r] {
			l++ // 矮的一侧是瓶颈，向内换人可能更高
		} else {
			r-- // 右侧不高于左侧，同理收缩右侧
		}
	}
	return ans
}

