def threeSum_tp(nums):
    nums.sort()                     # 排序：双指针的前提，也是去重的基础
    n, res = len(nums), []
    for i in range(n - 2):
        if nums[i] > 0:             # 剪枝：最小数都为正，后面不可能凑出 0
            break
        if i > 0 and nums[i] == nums[i - 1]:
            continue                # 去重1：跳过重复的固定数
        l, r = i + 1, n - 1         # 在 i 右侧区间找两数之和 = -nums[i]
        while l < r:
            s = nums[i] + nums[l] + nums[r]
            if s < 0:
                l += 1              # 和太小，左指针右移增大
            elif s > 0:
                r -= 1              # 和太大，右指针左移减小
            else:
                res.append([nums[i], nums[l], nums[r]])
                while l < r and nums[l] == nums[l + 1]:
                    l += 1          # 去重2：跳过左重复
                while l < r and nums[r] == nums[r - 1]:
                    r -= 1          # 去重3：跳过右重复
                l += 1
                r -= 1              # 指向新的不同元素，继续找
    return res

