// 输入格式：
//   第一行：n（数组长度）
//   第二行：n 个整数
// 输出格式：
//   第一行：不重复三元组的个数 k
//   接下来 k 行：每行一个三元组，元素升序、空格分隔（整体按字典序）
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);   // 关闭同步，读入更快
    cin.tie(nullptr);

    int n;
    cin >> n;
    vector<int> nums(n);
    for (auto& x : nums) cin >> x;
    sort(nums.begin(), nums.end());   // 排序：双指针的前提，也是去重的基础

    vector<array<int, 3>> res;
    for (int i = 0; i < n - 2; ++i) {
        if (nums[i] > 0) break;   // 剪枝：最小数都为正，不可能凑出 0
        if (i > 0 && nums[i] == nums[i - 1]) continue;   // 去重1：跳过重复的固定数
        int l = i + 1, r = n - 1;   // 在 i 右侧区间找两数之和 = -nums[i]
        while (l < r) {
            int s = nums[i] + nums[l] + nums[r];
            if (s < 0) {
                ++l;   // 和太小，左指针右移
            } else if (s > 0) {
                --r;   // 和太大，右指针左移
            } else {
                res.push_back({nums[i], nums[l], nums[r]});
                while (l < r && nums[l] == nums[l + 1]) ++l;   // 去重2：跳过左重复
                while (l < r && nums[r] == nums[r - 1]) --r;   // 去重3：跳过右重复
                ++l; --r;   // 指向新的不同元素，继续找
            }
        }
    }

    cout << res.size() << "\n";   // 第一行：三元组个数
    for (const auto& t : res)     // 每行一个三元组，元素升序、空格分隔
        cout << t[0] << " " << t[1] << " " << t[2] << "\n";
    return 0;
}

